import{_ as e,o as i,c as a,a2 as o}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Supported File Managers","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/file-manager-support.md","filePath":"user-guide/file-manager-support.md","lastUpdated":1785993908000}'),n={name:"user-guide/file-manager-support.md"};function d(l,t,r,s,h,c){return i(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="supported-file-managers" tabindex="-1">Supported File Managers <a class="header-anchor" href="#supported-file-managers" aria-label="Permalink to &quot;Supported File Managers&quot;">​</a></h1><p>Lertaro doesn&#39;t only search — it can also integrate with the file manager or dialog you&#39;re currently using. Depending on the target, that integration can mean up to three things:</p><ul><li><strong>Inline search docking</strong> — a Lertaro search bar embeds directly into the target window (the <a href="./getting-started.html#the-three-windows">inline window</a>), so you can search without leaving it.</li><li><strong>Quick Navigation</strong> — the target responds to the <a href="./hotkeys.html#quick-navigation-mouse">quick navigation mouse triggers</a> (double-click/middle-click, or the inline window&#39;s own logo), popping a cascading menu of Favorites, History, and quick-access folders.</li><li><strong>Active path detection</strong> — Lertaro can tell which folder is currently open in the target, so it can scope a search to that folder and resolve path-relative actions (like Copy Path) against it.</li></ul><p>Not every integration provides all three — see the table below.</p><h2 id="built-in-no-extra-install" tabindex="-1">Built in (no extra install) <a class="header-anchor" href="#built-in-no-extra-install" aria-label="Permalink to &quot;Built in (no extra install)&quot;">​</a></h2><p>These come bundled with Lertaro&#39;s core extensions plugin — nothing to enable separately.</p><table tabindex="0"><thead><tr><th>Target</th><th>Inline search docking</th><th>Quick Navigation</th><th>Active path detection</th></tr></thead><tbody><tr><td>Windows File Explorer</td><td>Yes</td><td>Double-click or middle-click</td><td>Yes</td></tr><tr><td>Modern Open/Save file dialog</td><td>Yes (this <em>is</em> the inline window)</td><td>Middle-click, or left-click the inline window&#39;s own logo</td><td>—</td></tr><tr><td>Classic Open/Save file dialog</td><td>Yes</td><td>Middle-click, or left-click the inline window&#39;s own logo</td><td>—</td></tr><tr><td>Classic Browse-for-Folder dialog</td><td>Yes</td><td>Middle-click, or left-click the inline window&#39;s own logo</td><td>—</td></tr></tbody></table><p>Active path detection doesn&#39;t apply to the dialogs themselves — there&#39;s no &quot;other window&quot; for Lertaro to scope a search against once it&#39;s already docked inside the dialog.</p><h2 id="optional-plugins-settings-→-plugins" tabindex="-1">Optional plugins (Settings → Plugins) <a class="header-anchor" href="#optional-plugins-settings-→-plugins" aria-label="Permalink to &quot;Optional plugins (Settings → Plugins)&quot;">​</a></h2><p>Each of these ships as its own plugin. Install/enable it from <a href="./settings/plugins.html">Settings → Plugins</a>, then use that plugin&#39;s own <strong>Configure</strong> dialog to toggle <strong>Enable Inline Search</strong> and <strong>Enable Quick Navigation</strong> independently — both default to on.</p><table tabindex="0"><thead><tr><th>Target</th><th>Inline search docking</th><th>Quick Navigation</th><th>Active path detection</th></tr></thead><tbody><tr><td>Directory Opus</td><td>Yes</td><td>Middle-click on a file list pane</td><td>Yes</td></tr><tr><td>Files</td><td>Yes</td><td>Middle-click on a file list pane</td><td>Yes</td></tr><tr><td>One Commander</td><td>Yes</td><td>Middle-click on a file list pane</td><td>Yes</td></tr><tr><td>Total Commander</td><td>Yes</td><td>Middle-click on a file list pane</td><td>Yes</td></tr><tr><td>XYplorer</td><td>Yes</td><td>Middle-click on a file list pane</td><td>Yes</td></tr></tbody></table><p>All five detect their target by matching the running process (and, for Directory Opus and Total Commander, by talking to their documented remote-control interface over <code>WM_COPYDATA</code> rather than scraping the UI); Files and One Commander instead use UI Automation, since neither exposes a remote-control protocol.</p><h2 id="application-dialogs-optional-plugins" tabindex="-1">Application dialogs (optional plugins) <a class="header-anchor" href="#application-dialogs-optional-plugins" aria-label="Permalink to &quot;Application dialogs (optional plugins)&quot;">​</a></h2><p>These target one specific dialog inside a third-party application — not the whole application — the same way the built-in dialogs above do. Install/enable from <a href="./settings/plugins.html">Settings → Plugins</a>; each ships a single component with its own on/off switch there (no separate Configure dialog, since there&#39;s only one thing to toggle).</p><table tabindex="0"><thead><tr><th>Target</th><th>Inline search docking</th><th>Quick Navigation</th><th>Active path detection</th></tr></thead><tbody><tr><td>WPS Office&#39;s Open/Save dialog</td><td>Yes</td><td>Middle-click, or left-click the inline window&#39;s own logo</td><td>—</td></tr><tr><td>WinRAR&#39;s Extract dialog</td><td>Yes</td><td>Middle-click, or left-click the inline window&#39;s own logo</td><td>—</td></tr><tr><td>Bandizip&#39;s Extract dialog</td><td>Yes</td><td>Middle-click, or left-click the inline window&#39;s own logo</td><td>—</td></tr><tr><td>Bandizip&#39;s Add Files dialog</td><td>Yes</td><td>Middle-click, or left-click the inline window&#39;s own logo</td><td>—</td></tr></tbody></table><p>Detected by control structure, not window title, so this works across every language pack each application ships. The WPS entry covers Writer, Spreadsheets, Presentation and the PDF reader, which all share the one dialog — WPS uses its own rather than the Windows one, which is why it needs a plugin at all where most applications are covered by the built-in dialogs above. As with those, active path detection doesn&#39;t apply — Lertaro is already docked inside the dialog itself, with no other window to scope a search against.</p><hr><p>Building your own integration for a file manager not listed here? See the <a href="./../dev-guide/sdk/system-adapters.html">System &amp; Dialog Adapters</a> reference in the Developer Manual.</p>',18)])])}const u=e(n,[["render",d]]);export{g as __pageData,u as default};
